package com.cyancoder.storefront.model;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="site_domain_events")
public class DomainEventEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="domain_id",nullable=false) private Long domainId; @Column(nullable=false,length=40) private String eventType; @Column(nullable=false,length=40) private String status; @Column(length=500) private String detail; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); protected DomainEventEntity(){} public DomainEventEntity(Long domainId,String eventType,String status,String detail){this.domainId=domainId;this.eventType=eventType;this.status=status;this.detail=detail;} public Long getId(){return id;} public Long getDomainId(){return domainId;} public String getEventType(){return eventType;} public String getStatus(){return status;} public String getDetail(){return detail;} public Instant getCreatedAt(){return createdAt;} }
